"""The views as they were before plan 1121; the builder versions must give the same rows. Each text is the
SELECT the database created for the view, taken from a fresh journal before any view moved to the builder."""

OLD_VIEWS = {
    'active_memories': "SELECT memories.id AS memory_id, memories.environment_id, memories.agent_id, memories.text, memories.weight FROM memories WHERE memories.state = 'active' AND memories.weight > 0",
    'agent_activities': "SELECT agents.id, agents.parent_id, agents.created_at, agents.ended_at, (SELECT hook_calls.created_at FROM hook_calls WHERE hook_calls.session_agent_id = agents.id AND hook_calls.hook <> 'tick' ORDER BY hook_calls.id DESC LIMIT 1) AS last_hook_at FROM agents",
    'agent_cards': 'SELECT agents.id, agents.number, agents.environment_id, agents.session, agents.role, agents.access, agents.program, agents.program_model, agents.profile, agents.given_name, agents.paused_at, agents.usage_limit_ends_at, agents.ended_at, agents.retired_at, agents.retirement_reason, (SELECT tasks.id FROM tasks WHERE tasks.holder_id = agents.id AND tasks.state = \'started\' ORDER BY tasks.id DESC LIMIT 1) AS started_task_id, coalesce((SELECT tasks.title FROM tasks WHERE tasks.holder_id = agents.id AND tasks.state = \'started\' ORDER BY tasks.id DESC LIMIT 1), \'\') AS started_task_title, (SELECT json_group_array(json_object(\'id\', listed.id, \'title\', listed.title, \'state\', listed.state, \'closed_at\', listed.closed_at, \'plan_id\', task_plan.id, \'plan_title\', task_plan.title)) FROM (SELECT tasks.id, tasks.title, tasks.state, coalesce(tasks.closed_at, \'\') AS closed_at, 0 AS part FROM tasks WHERE agents.role != \'main\' AND tasks.holder_id = agents.id AND coalesce((SELECT assignments.actor_id FROM assignments WHERE assignments.subject_model = \'task\' AND assignments.subject_id = tasks.id LIMIT 1), 0) != agents.id UNION ALL SELECT tasks.id, tasks.title, tasks.state, coalesce(tasks.closed_at, \'\') AS closed_at, 0 AS part FROM tasks WHERE agents.role = \'main\' AND tasks.id = (SELECT started.id FROM tasks AS started WHERE started.holder_id = agents.id AND started.state = \'started\' ORDER BY started.id DESC LIMIT 1) UNION ALL SELECT tasks.id, tasks.title, tasks.state, coalesce(tasks.closed_at, \'\') AS closed_at, 1 AS part FROM tasks WHERE tasks.id IN (SELECT assignments.subject_id FROM assignments WHERE assignments.subject_model = \'task\' AND assignments.actor_id = agents.id) ORDER BY part, id) AS listed LEFT JOIN phase_tasks ON phase_tasks.task_id = listed.id LEFT JOIN phases ON phases.id = phase_tasks.phase_id LEFT JOIN plans AS task_plan ON task_plan.id = phases.plan_id) AS tasks, CASE WHEN agents.ended_at IS NULL THEN coalesce((SELECT min(agent_blocks.created_at) FROM agent_blocks WHERE agent_blocks.session_agent_id = agents.id AND agent_blocks.closed_at IS NULL), \'\') ELSE \'\' END AS block_started_at, CASE WHEN agents.ended_at IS NULL THEN coalesce((SELECT agent_blocks.nudge_text FROM agent_blocks WHERE agent_blocks.session_agent_id = agents.id AND agent_blocks.closed_at IS NULL ORDER BY agent_blocks.id LIMIT 1), \'\') ELSE \'\' END AS block_reason, (agents.ended_at IS NULL AND EXISTS (SELECT 1 FROM tasks WHERE tasks.holder_id = agents.id AND tasks.state = \'blocked\')) AS task_blocked, coalesce((SELECT hook_calls.created_at FROM hook_calls WHERE hook_calls.session_agent_id = agents.id ORDER BY hook_calls.id DESC LIMIT 1), \'\') AS last_activity, coalesce(dispatch.program_model, \'\') AS job_model, coalesce(dispatch.profile, \'\') AS job_profile, coalesce(dispatch.description, \'\') AS job_description, coalesce(dispatch.instruction, \'\') AS job_instruction, coalesce(current_job.description, \'\') AS helper_job_description, coalesce(current_job.brief, \'\') AS helper_job_brief, coalesce(current_job.title, \'\') AS helper_job_title, coalesce(nullif(current_job.program, \'\'), agents.program) AS helper_job_program, current_job.new_session AS helper_job_new_session, (current_job.id IS NOT NULL AND current_job.started_at IS NOT NULL AND current_job.ended_at IS NULL) AS is_helper_job_open, json_extract(agents.metadata, \'$."journal.core.drivers".compaction_ended_at\') AS compaction_ended_at, (SELECT count(*) FROM agent_sessions WHERE agent_sessions.session_agent_id = agents.id) AS session_count, (SELECT agent_sessions.end_reason FROM agent_sessions WHERE agent_sessions.session_agent_id = agents.id AND agent_sessions.session != agents.session ORDER BY agent_sessions.id DESC LIMIT 1) AS replaced_session_end_reason, (SELECT count(*) FROM memories WHERE memories.environment_id = agents.environment_id AND memories.agent_id = agents.id AND memories.state = \'active\' AND memories.weight > 0) AS memory_count, (SELECT count(*) FROM messages WHERE messages.session_agent_id = agents.id AND messages.type = \'agent\' AND messages.is_chat_visible = 0) AS report_count, (SELECT actors.name FROM actors WHERE actors.id = agents.retiring_actor_id) AS retiring_actor_name, coalesce((SELECT messages.text FROM messages WHERE messages.session_agent_id = agents.id AND messages.creator_id = agents.id AND messages.type = \'agent\' AND messages.is_chat_visible = 0 ORDER BY messages.id DESC LIMIT 1), (SELECT latest.returned FROM helper_jobs AS latest WHERE latest.helper_id = agents.id ORDER BY latest.id DESC LIMIT 1), \'\') AS job_returned FROM agents LEFT JOIN helper_jobs AS dispatch ON dispatch.id = (SELECT min(helper_jobs.id) FROM helper_jobs WHERE helper_jobs.helper_id = agents.id) LEFT JOIN helper_jobs AS current_job ON current_job.id = (SELECT id FROM helper_jobs WHERE helper_id = agents.id ORDER BY ended_at IS NULL DESC, id DESC LIMIT 1)',
    'agent_counts': '\nSELECT environment_id, role, profile, count(*) AS kept,\n       sum(CASE WHEN ended_at IS NULL THEN 1 ELSE 0 END) AS running\nFROM agents WHERE retired_at IS NULL\nGROUP BY environment_id, role, profile',
    'agent_filter_options': 'SELECT environment_id, json_group_array(DISTINCT role) AS roles, json_group_array(DISTINCT profile) AS profiles FROM agents GROUP BY environment_id',
    'agent_listing': 'SELECT agent_cards.*, agents.parent_id, agents.created_at, agents.updated_at, agents.process_started_at FROM agent_cards JOIN agents ON agents.id = agent_cards.id',
    'attached_files': "SELECT messages.id || ':' || file.key AS row_key, messages.id AS message_id, messages.environment_id AS environment_id, file.value AS name, messages.text AS message_text, messages.created_at AS created_at FROM messages, json_each(messages.files) AS file",
    'chat_messages': 'SELECT id, environment_id, parent_id, type, text, read_at, files, captions, reactions, flowchart_edges, peer, recipient, COALESCE(json_extract(metadata, \'$."journal.core.messages".commented_row.model\') || \':\' || json_extract(metadata, \'$."journal.core.messages".commented_row.id\'), (SELECT target_model || \':\' || target_id FROM links WHERE source_model = \'message\' AND source_id = messages.id AND link_type = \'comments_on\' ORDER BY id LIMIT 1), \'\') AS commented_row, session_agent_id, target_agent_id, created_at FROM messages WHERE is_chat_visible = 1',
    'context_memories': "SELECT memory_deliveries.id AS delivery_id, memory_deliveries.session_agent_id, memory_deliveries.memory_id, memory_deliveries.cause, memory_deliveries.created_at AS delivered_at FROM memory_deliveries WHERE memory_deliveries.created_at > coalesce((SELECT max(hook_calls.created_at) FROM hook_calls WHERE hook_calls.session_agent_id = memory_deliveries.session_agent_id AND hook_calls.hook = 'compact'), '') AND memory_deliveries.created_at >= coalesce((SELECT coalesce(agent_sessions.started_at, agent_sessions.created_at) FROM agent_sessions WHERE agent_sessions.session_agent_id = memory_deliveries.session_agent_id ORDER BY agent_sessions.id DESC LIMIT 1), '')",
    'document_rows': "SELECT 'doc:' || id AS row_key, 'doc' AS row_type, id, title, abstract, close_reason, updated_at FROM docs UNION ALL SELECT 'report:' || id AS row_key, 'report' AS row_type, id, title, abstract, close_reason, updated_at FROM reports",
    'dump_rows': "SELECT 'dump:' || dumps.id AS row_key, 'dump' AS row_type, dumps.id AS dump_id, 0 AS item_id, 0 AS position, dumps.title, dumps.brief, dumps.outcome, '' AS text, '' AS state, '' AS note, '' AS summary, '[]' AS refs FROM dumps UNION ALL SELECT 'item:' || dump_items.id, 'item', dumps.id, dump_items.id, dump_items.position, '', '', '', dump_items.text, dump_items.state, dump_items.note, dump_items.summary, dump_items.refs FROM dump_items JOIN dumps ON dumps.id = dump_items.dump_id",
    'environment_cards': "SELECT environments.id, environments.name, environments.folder, environments.branch, (SELECT count(*) FROM agents WHERE agents.environment_id = environments.id AND agents.ended_at IS NULL) AS running_agent_count, (SELECT count(*) FROM tasks WHERE tasks.environment_id = environments.id AND tasks.state IN ('open', 'started', 'blocked', 'testing')) AS unfinished_task_count FROM environments WHERE environments.test = 0",
    'environment_menu_rows': "SELECT environments.id, environments.name, environments.folder, environments.branch, coalesce((SELECT json_extract(settings.value, '$') FROM settings WHERE settings.environment_id = environments.id AND settings.key = 'journal.core.drivers.suite'), (SELECT json_extract(settings.value, '$') FROM settings WHERE settings.environment_id IS NULL AND settings.key = 'journal.core.drivers.suite'), '') AS suite_setting, EXISTS (SELECT 1 FROM agents WHERE agents.environment_id = environments.id AND agents.role = 'main' AND agents.ended_at IS NULL) AS main_running FROM environments WHERE environments.test = 0",
    'hook_call_rows': 'SELECT id, session_agent_id, hook, tool, summary, answer, refusal, coalesce(json_extract(metadata, \'$."journal.core.drivers".stop_checks\'), \'[]\') AS stop_checks FROM hook_calls',
    'hook_request_rows': "\nSELECT id,\n       json_extract(payload, '$.received_at') AS received_at,\n       json_extract(payload, '$.program') AS program,\n       CAST(coalesce(nullif(json_extract(payload, '$.agent'), ''), '0') AS INTEGER) AS agent_id,\n       CASE json_extract(payload, '$.role') WHEN 'viewer' THEN 'viewer' WHEN 'cli' THEN 'command line' ELSE 'hook' END AS category,\n       CASE\n           WHEN coalesce(json_extract(payload, '$.body.event'), '') || ' ' LIKE 'process part-start %'\n             OR coalesce(json_extract(payload, '$.body.event'), '') || ' ' LIKE 'process part-end %'\n             OR coalesce(json_extract(payload, '$.body.event'), '') || ' ' LIKE 'process end %'\n             OR coalesce(json_extract(payload, '$.body.event'), '') || ' ' LIKE 'process start %'\n             OR coalesce(json_extract(payload, '$.body.event'), '') || ' ' LIKE 'process sandbox %' THEN 'process bookkeeping'\n           WHEN instr(coalesce(json_extract(payload, '$.body.event'), ''), ' ') > 0 THEN substr(json_extract(payload, '$.body.event'), 1, instr(json_extract(payload, '$.body.event'), ' ') - 1)\n           ELSE coalesce(json_extract(payload, '$.body.event'), json_extract(payload, '$.body.hook_event_name'), 'hook')\n       END AS family,\n       payload -> '$.headers' AS headers_json,\n       payload -> '$.body' AS body_json,\n       json_extract(payload, '$.duration_ms') AS duration_ms,\n       coalesce(json_extract(payload, '$.queued_ms'), 0) AS queued_ms, CAST(coalesce(json_extract(payload, '$.headers.\"X-Journal-Retries\"'), 0) AS INTEGER) AS retries,\n       CASE json_extract(payload, '$.role')\n           WHEN 'viewer' THEN 'Viewer'\n           WHEN 'cli' THEN 'Command line'\n           ELSE coalesce((SELECT json_extract(value, '$.label')\n                          || CASE WHEN coalesce(json_extract(payload, '$.agent'), '') <> ''\n                                  THEN ' ' || json_extract(payload, '$.agent') ELSE '' END\n                          FROM registry, json_each(registry.entries, '$.helper_types')\n                          WHERE json_extract(value, '$.key') = json_extract(payload, '$.role')), 'Main agent')\n       END AS sender,\n       json_extract(payload, '$.outcome') AS outcome,\n       coalesce(json_extract(payload, '$.body.event'), json_extract(payload, '$.body.hook_event_name'), 'hook') AS event,\n       coalesce(json_extract(payload, '$.body.tool.name'), json_extract(payload, '$.body.tool_name'), '') AS tool,\n       coalesce(json_array_length(payload, '$.body.tool.shell.parts'), 0) AS part_count,\n       substr(json_extract(payload, '$.received_at'), 1, 10) AS day,\n       substr(json_extract(payload, '$.received_at'), 12, 12) AS time,\n       lag(substr(json_extract(payload, '$.received_at'), 1, 10)) OVER (ORDER BY id DESC)\n           IS NOT substr(json_extract(payload, '$.received_at'), 1, 10) AS day_start\nFROM hook_requests",
    'keyword_memories': 'SELECT memory_keywords.id AS keyword_id, memory_keywords.word, active_memories.* FROM memory_keywords JOIN active_memories ON active_memories.memory_id = memory_keywords.memory_id',
    'main_chat_marks': "SELECT id, environment_id, session_agent_id, type, variant, key AS mark_key, text, detail, lines, target_model, target_id, outcome, figure, fraction, run_key, run_step, state, ended_at, created_at FROM chat_marks WHERE session_agent_id IS NULL OR session_agent_id IN (SELECT id FROM agents WHERE role = 'main')",
    'memory_holders': "SELECT agents.id AS agent_id, agents.environment_id, agents.role, CASE WHEN agents.role = 'main' THEN 'Main agent' ELSE upper(substr(agents.role, 1, 1)) || substr(agents.role, 2) || ' ' || agents.number END AS name, agents.created_at AS started_at, agents.ended_at, counts.active_memories, counts.removed_memories FROM agents JOIN (SELECT agent_id, sum(state = 'active') AS active_memories, sum(state = 'removed') AS removed_memories FROM memories WHERE agent_id IS NOT NULL GROUP BY agent_id) AS counts ON counts.agent_id = agents.id",
    'nudge_totals': "SELECT key AS nudge_key, sum(delivery_count) AS delivery_count, coalesce(max(last_delivered_at), '') AS last_delivered_at FROM nudge_records GROUP BY key",
    'open_dependencies': "SELECT task_dependencies.id, task_dependencies.task_id, task_dependencies.dependency_id FROM task_dependencies JOIN tasks ON tasks.id = task_dependencies.dependency_id JOIN tasks AS dependent ON dependent.id = task_dependencies.task_id WHERE tasks.closed_at IS NULL AND NOT (tasks.state IN ('started', 'testing') AND (SELECT assignments.actor_id FROM assignments WHERE assignments.subject_model = 'task' AND assignments.subject_id = tasks.id LIMIT 1) IS NOT NULL AND (SELECT assignments.actor_id FROM assignments WHERE assignments.subject_model = 'task' AND assignments.subject_id = tasks.id LIMIT 1) IS (SELECT assignments.actor_id FROM assignments WHERE assignments.subject_model = 'task' AND assignments.subject_id = dependent.id LIMIT 1))",
    'plan_cards': 'SELECT plans.id, plans.environment_id, plans.title, plans.state, plan_progress.task_count, plan_progress.completed_count, plan_progress.testing_count, plan_progress.current_phase, plan_progress.complexity, max(plans.updated_at, coalesce((SELECT max(tasks.updated_at) FROM plan_tasks JOIN tasks ON tasks.id = plan_tasks.task_id WHERE plan_tasks.plan_id = plans.id), plans.updated_at)) AS changed_at, (SELECT json_group_array(json_object(\'id\', helper.id, \'name\', CASE WHEN helper.role = \'main\' THEN \'Main agent\' ELSE upper(substr(helper.role, 1, 1)) || substr(helper.role, 2) || \' \' || helper.number END, \'main\', helper.role = \'main\', \'task_id\', tasks.id, \'task_title\', tasks.title)) FROM plan_tasks JOIN tasks ON tasks.id = plan_tasks.task_id JOIN agents AS helper ON helper.id = coalesce((SELECT assignments.actor_id FROM assignments WHERE assignments.subject_model = \'task\' AND assignments.subject_id = tasks.id LIMIT 1), tasks.holder_id) AND (helper.role != \'main\' OR (helper.id = (SELECT assignments.actor_id FROM assignments WHERE assignments.subject_model = \'task\' AND assignments.subject_id = tasks.id LIMIT 1) AND tasks.holder_id IS NULL)) WHERE plan_tasks.plan_id = plans.id AND plan_tasks.closed_at IS NULL) AS agents, (SELECT json_group_array(json_object(\'id\', tasks.id, \'title\', tasks.title)) FROM plan_tasks JOIN tasks ON tasks.id = plan_tasks.task_id WHERE plan_tasks.plan_id = plans.id AND plan_tasks.state = \'started\') AS working, (SELECT json_object(\'id\', assignee.id, \'name\', CASE WHEN assignee.role = \'main\' THEN \'Main agent\' ELSE upper(substr(assignee.role, 1, 1)) || substr(assignee.role, 2) || \' \' || assignee.number END, \'main\', assignee.role = \'main\') FROM agents AS assignee WHERE assignee.id = json_extract(plans.metadata, \'$."journal.core.plans".assignee_id\')) AS assignee FROM plans JOIN plan_progress ON plan_progress.plan_id = plans.id',
    'plan_event_rows': "SELECT plan_tasks.plan_id, 'made:' || tasks.id AS event_key, tasks.created_at AS time, 'made' AS event_type, tasks.id AS task_id, tasks.title, NULL AS text FROM plan_tasks JOIN tasks ON tasks.id = plan_tasks.task_id UNION ALL SELECT plan_tasks.plan_id, 'ended:' || tasks.id, tasks.closed_at, CASE WHEN tasks.state = 'cancelled' THEN 'cancelled' ELSE 'completed' END, tasks.id, tasks.title, CASE WHEN tasks.state = 'cancelled' THEN tasks.reason ELSE tasks.outcome END FROM plan_tasks JOIN tasks ON tasks.id = plan_tasks.task_id WHERE tasks.closed_at IS NOT NULL UNION ALL SELECT plan_tasks.plan_id, 'logged:' || task_logs.id, task_logs.created_at, 'logged', tasks.id, tasks.title, task_logs.line FROM task_logs JOIN plan_tasks ON plan_tasks.task_id = task_logs.task_id JOIN tasks ON tasks.id = task_logs.task_id",
    'plan_outline_tasks': "SELECT plan_tasks.task_id, plan_tasks.plan_id, plan_tasks.phase_id, plan_tasks.phase_position, plan_tasks.priority, plan_tasks.state, tasks.title, tasks.complexity, tasks.reason, tasks.delegated_to,  (SELECT coalesce('[' || group_concat(json_quote(word)) || ']', '[]') FROM (SELECT word FROM task_tags WHERE task_id = tasks.id ORDER BY word)) AS tags, (EXISTS(SELECT 1 FROM task_waits WHERE task_id = tasks.id AND ended_at IS NULL AND (command != '' OR target != 'user')) AND NOT EXISTS(SELECT 1 FROM task_waits WHERE task_id = tasks.id AND ended_at IS NULL AND target = 'user')) AS automatic, coalesce((SELECT agents.role = 'main' FROM agents WHERE agents.id = tasks.delegated_to), 0) AS main_delegate, helper.id AS helper_id, CASE WHEN helper.role = 'main' THEN 'Main agent' ELSE upper(substr(helper.role, 1, 1)) || substr(helper.role, 2) || ' ' || helper.number END AS helper_name, coalesce(helper.role = 'main', 0) AS helper_main FROM plan_tasks JOIN tasks ON tasks.id = plan_tasks.task_id LEFT JOIN agents AS helper ON helper.id = coalesce((SELECT assignments.actor_id FROM assignments WHERE assignments.subject_model = 'task' AND assignments.subject_id = tasks.id LIMIT 1), tasks.holder_id) AND (helper.role != 'main' OR (helper.id = (SELECT assignments.actor_id FROM assignments WHERE assignments.subject_model = 'task' AND assignments.subject_id = tasks.id LIMIT 1) AND tasks.holder_id IS NULL))",
    'plan_progress': "SELECT plans.id AS plan_id, (SELECT count(*) FROM plan_tasks WHERE plan_tasks.plan_id = plans.id AND plan_tasks.state != 'cancelled') AS task_count, (SELECT count(*) FROM plan_tasks WHERE plan_tasks.plan_id = plans.id AND plan_tasks.state = 'completed') AS completed_count, (SELECT count(*) FROM plan_tasks WHERE plan_tasks.plan_id = plans.id AND plan_tasks.state = 'testing') AS testing_count, coalesce((SELECT min(plan_tasks.phase_position) FROM plan_tasks WHERE plan_tasks.plan_id = plans.id AND plan_tasks.closed_at IS NULL), 0) AS current_phase, (SELECT round(avg(tasks.complexity), 1) FROM plan_tasks JOIN tasks ON tasks.id = plan_tasks.task_id WHERE plan_tasks.plan_id = plans.id AND plan_tasks.state != 'cancelled' AND tasks.complexity IS NOT NULL) AS complexity FROM plans",
    'plan_tasks': 'SELECT phase_tasks.task_id, phases.plan_id, phase_tasks.phase_id, phases.position AS phase_position, phases.checkpoint, phase_tasks.position, tasks.state, tasks.priority, tasks.closed_at, EXISTS (SELECT 1 FROM checkpoint_passes AS passes WHERE passes.plan_id = phases.plan_id AND passes.phase_id = phases.id) AS checkpoint_passed FROM phase_tasks JOIN phases ON phases.id = phase_tasks.phase_id JOIN tasks ON tasks.id = phase_tasks.task_id',
    'process_queue_rows': "\nSELECT processes.id, processes.environment_id, processes.session_agent_id, processes.line, processes.category,\n       processes.state, processes.exit_code, processes.created_at, processes.started_at, processes.ended_at,\n       processes.queued_at, processes.is_queue_run, processes.slot_assigned, processes.plugin,\n       agents.role = 'main' AS is_main,\n       coalesce(processes.owner_agent_id, CASE WHEN agents.role != 'main' THEN agents.id END) AS owner_agent_id,\n       coalesce(processes.task_id, (SELECT tasks.id FROM tasks WHERE (tasks.holder_id = processes.session_agent_id\n        OR tasks.id IN (SELECT assignments.subject_id FROM assignments WHERE assignments.subject_model = 'task' AND assignments.actor_id = processes.session_agent_id)) AND tasks.started_at <= processes.created_at\n        ORDER BY tasks.started_at DESC, tasks.id DESC LIMIT 1)) AS task_id,\n       CASE WHEN processes.state NOT IN ('running', 'background') THEN 'recent'\n            WHEN processes.queued_at IS NOT NULL THEN 'waiting' ELSE 'running' END AS section\nFROM processes JOIN agents ON agents.id = processes.session_agent_id\nWHERE processes.is_queue_run = 1\n   OR (agents.role = 'main' AND processes.category IN ('test run', 'build'))",
    'process_rows': 'SELECT id, environment_id, session_agent_id, line, state FROM processes',
    'reviewer_rows': "SELECT 'review:' || reviews.id AS row_key, reviews.environment_id, reviews.id AS review_id, reviews.state, reviews.subject_model, reviews.subject_id, 'review' AS row_type, 0 AS step_id, '' AS text, 'none' AS outcome, reviews.created_at FROM reviews WHERE reviews.state IN ('reviewing', 'queued') UNION ALL SELECT 'step:' || review_steps.id, reviews.environment_id, reviews.id, reviews.state, reviews.subject_model, reviews.subject_id, 'step', review_steps.id, review_steps.text, review_steps.outcome, review_steps.created_at FROM review_steps JOIN reviews ON reviews.id = review_steps.review_id WHERE reviews.state = 'reviewing'",
    'saved_commands': "SELECT id, name, line, category FROM aliases WHERE category IN ('test run', 'build')",
    'sequence_run_rows': 'SELECT sequence_runs.id, sequence_runs.environment_id, sequence_runs.session_agent_id, sequence_runs.sequence_id, sequences.title, sequences.steps, sequence_runs.step_number, sequence_runs.step_started, sequence_runs.created_at FROM sequence_runs JOIN sequences ON sequences.id = sequence_runs.sequence_id WHERE sequence_runs.ended_at IS NULL',
    'task_block_reviews': "SELECT tasks.id AS task_id, agents.id AS session_agent_id, tasks.environment_id, tasks.state, tasks.version AS task_version, coalesce((SELECT max(task_version) FROM task_block_renewals WHERE task_id = tasks.id), 0) AS block_version, max(coalesce((SELECT max(created_at) FROM task_block_renewals WHERE task_id = tasks.id), tasks.updated_at), coalesce((SELECT max(last_delivered_at) FROM nudge_records WHERE session_agent_id = agents.id AND key = 'tasks.block_review.' || tasks.id), '')) AS reviewed_at, max(tasks.updated_at, coalesce((SELECT max(created_at) FROM task_block_renewals WHERE task_id = tasks.id), '')) AS moved_at, EXISTS(SELECT 1 FROM task_waits WHERE task_id = tasks.id AND ended_at IS NULL AND target = 'user') AS user_wait, EXISTS(SELECT 1 FROM task_waits WHERE task_id = tasks.id AND ended_at IS NULL AND (command != '' OR target != 'user')) AS automatic FROM tasks JOIN agents ON agents.environment_id = tasks.environment_id AND agents.role = 'main'",
    'task_cards': "SELECT tasks.id, tasks.environment_id, tasks.title, tasks.state, tasks.priority, tasks.complexity, tasks.reason, tasks.closed_at, (SELECT assignments.actor_id FROM assignments WHERE assignments.subject_model = 'task' AND assignments.subject_id = tasks.id LIMIT 1) AS assigned_actor_id,  (SELECT coalesce('[' || group_concat(json_quote(word)) || ']', '[]') FROM (SELECT word FROM task_tags WHERE task_id = tasks.id ORDER BY word)) AS tags, (EXISTS(SELECT 1 FROM task_waits WHERE task_id = tasks.id AND ended_at IS NULL AND (command != '' OR target != 'user')) AND NOT EXISTS(SELECT 1 FROM task_waits WHERE task_id = tasks.id AND ended_at IS NULL AND target = 'user')) AS automatic,  (SELECT CASE WHEN actors.type = 'agent' THEN (SELECT CASE WHEN agents.role = 'main' THEN 'Main agent' ELSE upper(substr(agents.role, 1, 1)) || substr(agents.role, 2) || ' ' || agents.number END FROM agents WHERE agents.id = actors.id) ELSE actors.name END FROM actors WHERE actors.id = (SELECT assignments.actor_id FROM assignments WHERE assignments.subject_model = 'task' AND assignments.subject_id = tasks.id LIMIT 1)) AS assigned_name, (SELECT actors.type FROM actors WHERE actors.id = (SELECT assignments.actor_id FROM assignments WHERE assignments.subject_model = 'task' AND assignments.subject_id = tasks.id LIMIT 1)) AS assigned_type, coalesce((SELECT agents.role = 'main' FROM agents WHERE agents.id = (SELECT assignments.actor_id FROM assignments WHERE assignments.subject_model = 'task' AND assignments.subject_id = tasks.id LIMIT 1)), 0) AS is_main_assignee FROM tasks",
    'task_edges': "SELECT task_id, dependency_id AS blocker_id FROM task_dependencies UNION SELECT task_id, CAST(substr(target, 7) AS INTEGER) FROM task_waits WHERE ended_at IS NULL AND target LIKE 'tasks:%'",
    'task_inspections': "SELECT tasks.id AS task_id,  (SELECT coalesce('[' || group_concat(json_quote(word)) || ']', '[]') FROM (SELECT word FROM task_tags WHERE task_id = tasks.id ORDER BY word)) AS tags, (SELECT json_group_array(json_object('id', waited.id, 'title', waited.title, 'state', waited.state)) FROM task_dependencies JOIN tasks AS waited ON waited.id = task_dependencies.dependency_id WHERE task_dependencies.task_id = tasks.id) AS waits, (SELECT json_group_array(json_object('id', latest.id, 'line', latest.line, 'created_at', latest.created_at)) FROM (SELECT task_logs.id, task_logs.line, task_logs.created_at FROM task_logs WHERE task_logs.task_id = tasks.id ORDER BY task_logs.id DESC LIMIT 100) AS latest) AS logs, (SELECT json_group_array(json_object('id', task_waits.id, 'command', task_waits.command, 'target', task_waits.target)) FROM task_waits WHERE task_waits.task_id = tasks.id AND task_waits.ended_at IS NULL) AS openers, (SELECT json_group_array(json_object('id', renewal.id, 'reason', renewal.reason, 'created_at', renewal.created_at)) FROM (SELECT id, reason, created_at FROM task_block_renewals WHERE task_id = tasks.id ORDER BY id) AS renewal) AS block_renewals, helper.id AS helper_id, CASE WHEN helper.role = 'main' THEN 'Main agent' ELSE upper(substr(helper.role, 1, 1)) || substr(helper.role, 2) || ' ' || helper.number END AS helper_name, coalesce(helper.role = 'main', 0) AS helper_main FROM tasks LEFT JOIN agents AS helper ON helper.id = coalesce((SELECT assignments.actor_id FROM assignments WHERE assignments.subject_model = 'task' AND assignments.subject_id = tasks.id LIMIT 1), tasks.holder_id) AND (helper.role != 'main' OR (helper.id = (SELECT assignments.actor_id FROM assignments WHERE assignments.subject_model = 'task' AND assignments.subject_id = tasks.id LIMIT 1) AND tasks.holder_id IS NULL))",
    'task_tag_words': 'SELECT word, count(*) AS count FROM task_tags GROUP BY word',
    'waiting_rows': "SELECT waits.id, waits.focus, waits.state, waits.opened_at, coalesce((SELECT group_concat(wait_targets.row_table || ':' || wait_targets.row_id, ', ') FROM wait_targets WHERE wait_targets.wait_id = waits.id), '') AS targets FROM waits WHERE waits.state = 'open' AND (waits.type IN ('help_request', 'answer') OR EXISTS (SELECT 1 FROM wait_targets WHERE wait_targets.wait_id = waits.id AND wait_targets.row_table = 'questions'))",
    'worker_points': "SELECT worker_worktrees.id AS worktree_id, worker_worktrees.session_agent_id, tasks.title AS task_title, tasks.brief AS task_brief, (SELECT json_group_array(json_object('point', proofs.point, 'state', proofs.state, 'text', proofs.text, 'shortfall', proofs.shortfall)) FROM proofs WHERE proofs.worktree_id = worker_worktrees.id AND proofs.task_id = worker_worktrees.task_id) AS proofs FROM worker_worktrees JOIN tasks ON tasks.id = worker_worktrees.task_id",
    'worker_progress': "\nSELECT worktree.session_agent_id AS agent_id, worktree.environment_id, worktree.branch, worktree.task_id,\n       coalesce(worktree.cut_at, worktree.created_at) AS started_at,\n       worktree.removed_at AS finished_at,\n       count(tasks.id) AS task_count,\n       count(CASE WHEN tasks.state IN ('completed', 'testing') THEN 1 END) AS completed_count\nFROM worker_worktrees AS worktree\nLEFT JOIN tasks ON tasks.id IN (SELECT assignments.subject_id FROM assignments WHERE assignments.subject_model = 'task' AND assignments.actor_id = worktree.session_agent_id\n                                UNION SELECT held.id FROM tasks AS held WHERE held.holder_id = worktree.session_agent_id)\n    AND (tasks.closed_at IS NULL OR tasks.closed_at >= coalesce(worktree.cut_at, worktree.created_at))\nWHERE worktree.id = (SELECT max(latest.id) FROM worker_worktrees AS latest WHERE latest.session_agent_id = worktree.session_agent_id)\nGROUP BY worktree.environment_id, worktree.id",
    'worker_waits': "\nSELECT worktree.session_agent_id AS agent_id, worktree.environment_id,\n       CASE\n           WHEN EXISTS (SELECT 1 FROM tasks WHERE tasks.holder_id = worktree.session_agent_id AND tasks.state = 'started')\n               THEN CASE\n                   WHEN agents.ended_at IS NULL THEN ''\n                   WHEN EXISTS (SELECT 1 FROM reader_requests WHERE reader_requests.creator_id = worktree.session_agent_id AND reader_requests.completed_at IS NULL)\n                       THEN 'reader'\n                   WHEN EXISTS (SELECT 1 FROM processes WHERE processes.session_agent_id = worktree.session_agent_id AND processes.state IN ('running', 'background') AND processes.queued_at IS NOT NULL)\n                       THEN 'place in the queue'\n                   WHEN EXISTS (SELECT 1 FROM processes WHERE processes.session_agent_id = worktree.session_agent_id AND processes.state IN ('running', 'background'))\n                       THEN 'command to finish'\n                   ELSE 'next start'\n               END\n           WHEN EXISTS (SELECT 1 FROM proofs WHERE proofs.worktree_id = worktree.id AND proofs.state IN ('queued', 'running'))\n               THEN 'tests'\n           WHEN worktree.state = 'delivered' AND EXISTS (\n               SELECT 1 FROM proofs WHERE proofs.worktree_id = worktree.id AND proofs.state = 'shown')\n               THEN 'proof check'\n           WHEN worktree.state = 'delivered' THEN 'merge'\n           WHEN worktree.state = 'cut' AND NOT EXISTS (\n               SELECT 1 FROM tasks WHERE (SELECT assignments.actor_id FROM assignments WHERE assignments.subject_model = 'task' AND assignments.subject_id = tasks.id LIMIT 1) = worktree.session_agent_id AND tasks.state IN ('open', 'started', 'testing', 'blocked'))\n               THEN 'a job'\n           WHEN agents.ended_at IS NOT NULL THEN 'a job'\n           ELSE ''\n       END AS reason\nFROM worker_worktrees AS worktree\nJOIN agents ON agents.id = worktree.session_agent_id\nWHERE worktree.removed_at IS NULL\n  AND worktree.id = (SELECT max(latest.id) FROM worker_worktrees AS latest WHERE latest.session_agent_id = worktree.session_agent_id)",
    'worker_work_reviews': "\nSELECT worktree.session_agent_id AS agent_id, worktree.environment_id,\n       CASE\n           WHEN worktree.state = 'cut' THEN 'changes requested'\n           WHEN worktree.returned_at IS NOT NULL THEN 'with the main agent'\n           WHEN EXISTS (SELECT 1 FROM proofs JOIN processes ON processes.id = proofs.process_id\n                        WHERE proofs.worktree_id = worktree.id AND proofs.state = 'running' AND processes.queued_at IS NULL) THEN 'tests running'\n           WHEN EXISTS (SELECT 1 FROM proofs WHERE proofs.worktree_id = worktree.id AND proofs.state IN ('queued', 'running')) THEN 'tests queued'\n           WHEN worktree.merge_ready_at IS NULL THEN 'judging'\n           ELSE 'waiting for the merge'\n       END AS status\nFROM worker_worktrees AS worktree\nJOIN agents ON agents.id = worktree.session_agent_id\nWHERE worktree.delivered_at IS NOT NULL\n  AND worktree.state IN ('cut', 'delivered')\n  AND worktree.removed_at IS NULL AND agents.retired_at IS NULL",
}
